<?php
 namespace Pterodactyl\Services\Dezerx\Databases; use Generator; use Throwable; use Pterodactyl\Models\Database; use Illuminate\Database\DatabaseManager; use Illuminate\Database\Connection; use Pterodactyl\Extensions\DynamicDatabaseConnection; class DatabaseTransfer { public const CONNECTION = 'dezerx-transfer'; public const MAX_UPLOAD_KB = 262144; private const ROW_CHUNK = 200; private const STATEMENT_LIMIT = 200000; public function __construct( private DynamicDatabaseConnection $dynamic, private DatabaseManager $manager, ) { } public function connection(Database $database): Connection { $host = $database->host()->firstOrFail(); config()->set('database.connections.' . self::CONNECTION, ['driver' => 'mysql', 'host' => $host->host, 'port' => $host->port, 'database' => $database->database, 'username' => $database->username, 'password' => app(\Illuminate\Contracts\Encryption\Encrypter::class)->decrypt($database->password), 'charset' => 'utf8mb4', 'collation' => 'utf8mb4_unicode_ci']); $this->manager->purge(self::CONNECTION); return $this->manager->connection(self::CONNECTION); } public function filename(Database $database): string { $stem = preg_replace('/[^A-Za-z0-9_.-]/', '-', $database->database) ?: 'database'; return $stem . '-' . date('Ymd-His') . '.sql'; } public function size(Database $database): ?int { try { $rows = $this->connection($database)->select( 'SELECT SUM(data_length + index_length) AS bytes FROM information_schema.tables WHERE table_schema = ?', [$database->database], ); } catch (Throwable) { return null; } $bytes = $rows[0]->bytes ?? null; return $bytes === null ? null : (int) $bytes; } public function tables(Database $database): ?int { try { return count($this->connection($database)->select('SHOW FULL TABLES')); } catch (Throwable) { return null; } } public function export(Database $database): Generator { $connection = $this->connection($database); $name = $database->database; yield "-- Export of `{$name}`\n"; yield '-- Taken ' . gmdate('Y-m-d H:i:s') . " UTC\n\n"; yield "SET FOREIGN_KEY_CHECKS = 0;\n"; yield "SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';\n"; yield "SET NAMES utf8mb4;\n\n"; $views = []; foreach ($connection->select('SHOW FULL TABLES') as $row) { $fields = array_values((array) $row); $table = (string) ($fields[0] ?? ''); $kind = (string) ($fields[1] ?? 'BASE TABLE'); if ($table === '') { continue; } if ($kind === 'VIEW') { $views[] = $table; continue; } yield from $this->dumpTable($connection, $table); } foreach ($views as $view) { yield from $this->dumpView($connection, $view); } yield "SET FOREIGN_KEY_CHECKS = 1;\n"; } private function dumpTable(Connection $connection, string $table): Generator { $quoted = $this->quoteName($table); yield "DROP TABLE IF EXISTS {$quoted};\n"; $create = (array) $connection->select("SHOW CREATE TABLE {$quoted}")[0]; yield (string) (array_values($create)[1] ?? '') . ";\n\n"; $columns = array_map( fn (object $column) => (string) (array_values((array) $column)[0] ?? ''), $connection->select("SHOW COLUMNS FROM {$quoted}"), ); if ($columns === []) { return; } $list = implode(', ', array_map(fn (string $column) => $this->quoteName($column), $columns)); $buffer = []; foreach ($connection->cursor("SELECT * FROM {$quoted}") as $row) { $values = []; foreach ($columns as $column) { $values[] = $this->literal(((array) $row)[$column] ?? null); } $buffer[] = '(' . implode(',', $values) . ')'; if (count($buffer) >= self::ROW_CHUNK) { yield "INSERT INTO {$quoted} ({$list}) VALUES\n" . implode(",\n", $buffer) . ";\n"; $buffer = []; } } if ($buffer !== []) { yield "INSERT INTO {$quoted} ({$list}) VALUES\n" . implode(",\n", $buffer) . ";\n"; } yield "\n"; } private function dumpView(Connection $connection, string $view): Generator { $quoted = $this->quoteName($view); yield "DROP VIEW IF EXISTS {$quoted};\n"; try { $create = (array) $connection->select("SHOW CREATE VIEW {$quoted}")[0]; } catch (Throwable) { return; } $sql = (string) (array_values($create)[1] ?? ''); yield preg_replace('/DEFINER=`[^`]*`@`[^`]*` /', '', $sql) . ";\n\n"; } public function import(Database $database, string $sql): array { $connection = $this->connection($database); $ran = 0; $failed = []; $connection->getPdo()->exec('SET FOREIGN_KEY_CHECKS = 0'); foreach ($this->statements($sql) as $statement) { try { $connection->getPdo()->exec($statement); $ran++; } catch (Throwable $exception) { if (count($failed) < 5) { $failed[] = $this->describeFailure($statement, $exception); } } } $connection->getPdo()->exec('SET FOREIGN_KEY_CHECKS = 1'); return ['statements' => $ran, 'failed' => $failed]; } public function wipe(Database $database): int { $connection = $this->connection($database); $dropped = 0; $connection->getPdo()->exec('SET FOREIGN_KEY_CHECKS = 0'); foreach ($connection->select('SHOW FULL TABLES') as $row) { $fields = array_values((array) $row); $name = (string) ($fields[0] ?? ''); $kind = (string) ($fields[1] ?? 'BASE TABLE'); if ($name === '') { continue; } $quoted = $this->quoteName($name); try { $connection->getPdo()->exec($kind === 'VIEW' ? "DROP VIEW {$quoted}" : "DROP TABLE {$quoted}"); $dropped++; } catch (Throwable) { } } $connection->getPdo()->exec('SET FOREIGN_KEY_CHECKS = 1'); return $dropped; } public function statements(string $sql): Generator { $length = strlen($sql); $buffer = ''; $quote = null; $emitted = 0; for ($index = 0; $index < $length; $index++) { $character = $sql[$index]; if ($quote !== null) { $buffer .= $character; if ($character === '\\' && $quote !== '`' && $index + 1 < $length) { $buffer .= $sql[++$index]; continue; } if ($character === $quote) { $quote = null; } continue; } if ($character === "'" || $character === '"' || $character === '`') { $quote = $character; $buffer .= $character; continue; } if ($character === '-' && substr($sql, $index, 3) === '-- ') { $index = $this->skipToNewline($sql, $index); continue; } if ($character === '#') { $index = $this->skipToNewline($sql, $index); continue; } if ($character === '/' && substr($sql, $index, 2) === '/*') { $end = strpos($sql, '*/', $index + 2); $index = $end === false ? $length : $end + 1; continue; } if ($character === ';') { $statement = trim($buffer); $buffer = ''; if ($statement !== '') { $emitted++; if ($emitted > self::STATEMENT_LIMIT) { return; } yield $statement; } continue; } $buffer .= $character; } $statement = trim($buffer); if ($statement !== '' && $emitted < self::STATEMENT_LIMIT) { yield $statement; } } private function skipToNewline(string $sql, int $index): int { $end = strpos($sql, "\n", $index); return $end === false ? strlen($sql) : $end; } private function describeFailure(string $statement, Throwable $exception): string { $head = preg_replace('/\s+/', ' ', substr($statement, 0, 80)); return trim((string) $head) . ': ' . $exception->getMessage(); } private function quoteName(string $name): string { return '`' . str_replace('`', '``', $name) . '`'; } private function literal(mixed $value): string { if ($value === null) { return 'NULL'; } if (is_bool($value)) { return $value ? '1' : '0'; } if (is_int($value) || is_float($value)) { return (string) $value; } $text = (string) $value; if (!mb_check_encoding($text, 'UTF-8')) { return '0x' . bin2hex($text); } return "'" . str_replace( ['\\', "'", "\0", "\n", "\r", "\x1a"], ['\\\\', "\\'", '\\0', '\\n', '\\r', '\\Z'], $text, ) . "'"; } } 